use mergesort::merge_sort;

#[test]
fn test_empty() {
    assert_eq!(merge_sort(&[]), vec![]);
}

#[test]
fn test_single() {
    assert_eq!(merge_sort(&[42]), vec![42]);
}

#[test]
fn test_sorted() {
    assert_eq!(merge_sort(&[1, 2, 3, 4, 5]), vec![1, 2, 3, 4, 5]);
}

#[test]
fn test_reverse() {
    assert_eq!(merge_sort(&[5, 4, 3, 2, 1]), vec![1, 2, 3, 4, 5]);
}

#[test]
fn test_random() {
    assert_eq!(merge_sort(&[3, 1, 4, 1, 5, 9, 2, 6]), vec![1, 1, 2, 3, 4, 5, 6, 9]);
}

#[test]
fn test_duplicates() {
    assert_eq!(merge_sort(&[2, 2, 1, 1]), vec![1, 1, 2, 2]);
}
